package world

import (
	"atlas/internal/anvil"
	"atlas/internal/worldgen"
	"os"
	"path/filepath"
	"testing"
)

// A coarse independent check of the interpolated final-density stage against
// blocks generated by the supplied 1.21.1 server. This checks solid/air at
// points well away from the zero boundary; it does not validate aquifers,
// surface rules, features, structures, or exact density values.
func TestOverworldDensitySignAgainstVanillaChunk(t *testing.T) {
	dir := filepath.Join("..", "..", "vanilla", "world")
	if _, err := os.Stat(filepath.Join(dir, "level.dat")); os.IsNotExist(err) {
		t.Skip("vanilla reference save unavailable")
	}
	v, err := openVanilla(dir)
	if err != nil {
		t.Fatal(err)
	}
	if v.flat != nil {
		t.Skip("reference save is not a noise world")
	}
	name, root, exists, err := anvil.ReadChunk(filepath.Join(dir, "region"), 0, 0)
	if err != nil || !exists {
		t.Fatalf("reference chunk 0,0: exists=%v error=%v", exists, err)
	}
	chunk, err := chunkFromAnvil(name, root, 0, 0)
	if err != nil {
		t.Fatal(err)
	}
	settings, err := worldgen.LoadDensitySettings("overworld")
	if err != nil {
		t.Fatal(err)
	}
	sampler := worldgen.NewCellDensitySampler(v.seed, settings)
	count := 0
	for _, y := range []int32{-50, -40, 20, 50, 80, 100} {
		for _, xz := range [][2]int32{{0, 0}, {5, 5}, {8, 8}, {15, 15}} {
			density, err := sampler.Sample(settings.Router["final_density"], xz[0], y, xz[1])
			if err != nil {
				t.Fatal(err)
			}
			state := chunk.GetBlock(int(xz[0]), int(xz[1]), y)
			if density > 0.01 && isAir(state) || density < -0.01 && !isAir(state) {
				t.Errorf("%d,%d,%d: density %f conflicts with vanilla state %d", xz[0], y, xz[1], density, state)
			}
			count++
		}
	}
	t.Logf("checked %d solid/air positions against the vanilla chunk", count)
}
